      hu: ["A csata ideje: 1944. szeptember-november", "Helyszín: Peleliu-sziget", "Magasság: kb. 75 méter a tengerszint felett", "Jellemző: több száz megerősített barlang", "Emlékművek: amerikai és japán egyaránt található", "Hadi maradványok: harckocsi roncsok és ágyúk láthatók"],
      ro: ["Data bătăliei: septembrie - noiembrie 1944", "Locație: Insula Peleliu", "Înălțime: cca. 75 metri peste nivelul mării", "Caracteristică: sute de peșteri fortificate", "Monumente: atât americane, cât și japoneze", "Echipament: epave de tancuri și tunuri vizibile"],
      en: ["Battle date: September to November 1944", "Location: Peleliu Island", "Elevation: approx. 75 meters above sea level", "Feature: hundreds of fortified caves", "Monuments: both U.S. and Japanese markers", "War relics: tank wrecks and artillery still present"],
      es: ["Fecha de la batalla: septiembre a noviembre de 1944", "Ubicación: Isla de Peleliu", "Altura: aprox. 75 metros sobre el nivel del mar", "Particularidad: Cientos de cuevas fortificadas", "Monumentos: Tanto estadounidenses como japoneses", "Material de guerra: Restos de tanques y cañones aún visibles"],
      pt: ["Data da batalha: setembro a novembro de 1944", "Localização: Ilha de Peleliu", "Altura: cerca de 75 metros acima do mar", "Particularidade: Centenas de cavernas fortificadas", "Monumentos: Tanto americanos quanto japoneses", "Equipamento de guerra: Destroços de tanques e canhões ainda visíveis"],
      fr: ["Date de la bataille : septembre à novembre 1944", "Lieu : Île de Peleliu", "Altitude : environ 75 mètres au-dessus de la mer", "Particularité : Des centaines de grottes fortifiées", "Monuments : À la fois américains et japonais", "Matériel de guerre : Épaves de chars et canons encore visibles"],
